export interface Minhas_tarefasContracts {
  /**
   * Finalidade: Carrega a abertura de minhas tarefas: a primeira página do que depende da pessoa da sessão agora, os totais de cada grupo e de vencimento, e se ela pode criar tarefas.
   * Entrada: page e pageSize: página e tamanho da página do grupo ’depende de mim agora’.
   * Processamento: Filtra as tarefas em que a pessoa da sessão é quem age agora (membroVeResponsavelOuCriador), ordenadas por atrasada, vence hoje e criadaEm. quemAgeAgora é calculado pela situação (quemAgeAgoraPorSituacao); aberta, venceHoje e atrasada são calculados pela data de hoje (tarefaAbertaVencimento); progressoChecklist conta itens concluídos sobre o total. Conta no servidor as tarefas abertas de que é responsável, as que criou, as que dependem dela, as que vencem hoje e as atrasadas. possoCriar é a marca efetiva de poder criar tarefas da pessoa da sessão, valendo sim quando não configurada (participanteNaoConfiguradoAceitaECria, criarTarefaExigePodeCriar). Campos derivados são calculados, nunca gravados.
   * Saída: Página { items, page, pageSize, hasMore } de tarefas resumidas que dependem da pessoa agora, os totais por grupo e de vencimento e o indicador podeCriarTarefasEfetivo.
   */
  'tarefas.minhas_tarefas.qryMinhasTarefas': {
    kind: 'qry';
    input: { page: number; pageSize: number };
    output: { tarefas: { items: TarefaResumo[]; page: number; pageSize: number; hasMore: boolean }; readonly quantidadeDependeDeMim: number; readonly quantidadeResponsavel: number; readonly quantidadeCriadas: number; readonly quantidadeVenceHoje: number; readonly quantidadeAtrasadas: number; readonly podeCriarTarefasEfetivo: boolean };
    rules: ['membroVeResponsavelOuCriador', 'quemAgeAgoraPorSituacao', 'tarefaAbertaVencimento', 'participanteNaoConfiguradoAceitaECria', 'criarTarefaExigePodeCriar'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Busca uma página das tarefas da pessoa da sessão num grupo: responsável, criadas ou depende de mim agora.
   * Entrada: grupo: ’responsavel’, ’criadas’ ou ’dependeDeMim’; page e pageSize: página pedida e tamanho.
   * Processamento: Filtra por responsavelId, criadorId ou quemAgeAgora igual à pessoa da sessão conforme o grupo (membroVeResponsavelOuCriador), abertas primeiro, atrasadas e que vencem hoje antes, depois criadaEm. Calcula quemAgeAgora (quemAgeAgoraPorSituacao), aberta, venceHoje, atrasada (tarefaAbertaVencimento), devolvidaPendente e progressoChecklist; nada é gravado.
   * Saída: Página { items, page, pageSize, hasMore } de tarefas resumidas do grupo pedido.
   */
  'tarefas.minhas_tarefas.qryTarefasDoGrupo': {
    kind: 'qry';
    input: { grupo: string; page: number; pageSize: number };
    output: { tarefas: { items: TarefaResumo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['membroVeResponsavelOuCriador', 'quemAgeAgoraPorSituacao', 'tarefaAbertaVencimento'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Abre uma tarefa com seus dados, checklist, papel da pessoa da sessão e histórico.
   * Entrada: tarefaId: id da tarefa escolhida na lista ou vinda de um aviso.
   * Processamento: Lê a tarefa pelo id e recusa se a pessoa da sessão não for responsável, quem criou nem quem age agora (membroVeResponsavelOuCriador). Compõe nomes do responsável, de quem criou e de quem age agora, nome da lista, título da tarefa pai, quantidade de subtarefas, progressoChecklist e os itens da checklist em ordem (itemChecklistSoQuemVeTarefa). Calcula quemAgeAgora pela situação (quemAgeAgoraPorSituacao), souResponsavel e souCriador comparando com a pessoa da sessão. Monta o histórico pelos marcos da tarefa e do processo da plataforma, em ordem de tempo; comentários e anexos ficam na conversa da plataforma (moduloNaoGuardaComentarios).
   * Saída: A tarefa completa com a checklist em ordem e a lista de eventos do histórico em ordem cronológica.
   */
  'tarefas.minhas_tarefas.qryTarefa': {
    kind: 'qry';
    input: { tarefaId: string };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['membroVeResponsavelOuCriador', 'quemAgeAgoraPorSituacao', 'itemChecklistSoQuemVeTarefa', 'moduloNaoGuardaComentarios'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Busca pelo nome os participantes que podem ser escolhidos como responsável.
   * Entrada: busca: trecho do nome digitado; vazio traz os primeiros por nome.
   * Processamento: Filtra participantes com o papel tarefas.Participante, situação Active e aceitaTarefasEfetivo verdadeiro, valendo sim quando não configurado (responsavelAceitaTarefas, participanteNaoConfiguradoAceitaECria). Busca só pelo nome, nunca pelo e-mail (escolhaResponsavelPeloNome), e não expõe outro dado pessoal (participanteSemCadastroPessoal). Limita a uma quantidade curta, ordenada por nome.
   * Saída: Participantes elegíveis com id, nome, situação e aceita tarefas efetivo.
   */
  'tarefas.minhas_tarefas.qryResponsaveis': {
    kind: 'qry';
    input: { busca?: string };
    output: { participantes: ParticipanteOpcao[] };
    rules: ['escolhaResponsavelPeloNome', 'responsavelAceitaTarefas', 'participanteNaoConfiguradoAceitaECria', 'participanteSemCadastroPessoal'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Busca as listas de tarefas pelo nome para escolher a lista da tarefa.
   * Entrada: busca: trecho do nome da lista; vazio traz as primeiras por nome.
   * Processamento: Busca listas pelo texto no nome, ordenadas por nome, limitadas a uma quantidade curta.
   * Saída: Listas com id e nome.
   */
  'tarefas.minhas_tarefas.qryListas': {
    kind: 'qry';
    input: { busca?: string };
    output: { listas: ListaTarefasNome[] };
    rules: [];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Cria uma nova tarefa em a fazer com o responsável escolhido.
   * Entrada: titulo, details.descricao, prioridade, prazo, listaId, responsavelId, tarefaPaiId opcional e details.etiquetas da nova tarefa; criadorId: quem cria, que precisa ser a própria pessoa da sessão.
   * Processamento: Recusa se a pessoa da sessão não puder criar tarefas pela marca efetiva (criarTarefaExigePodeCriar, podeCriarTarefasExigido, participanteNaoConfiguradoAceitaECria) e recusa criadorId diferente da pessoa da sessão: quem criou é sempre ela (criarTarefaExigePodeCriar). Recusa responsável que não seja participante ativo que aceita tarefas (responsavelAceitaTarefas, escolhaResponsavelPeloNome) e tarefa pai inválida (tarefaPaiDiferenteDaPropria). Grava com status aFazer; criadaEm é preenchido pelo sistema. Abre a ocorrência do processo da tarefa e avisa o responsável (avisarQuemAgeAgora).
   * Saída: A tarefa criada, em a fazer, completa e com checklist vazia, e seu histórico com o evento de criação.
   */
  'tarefas.minhas_tarefas.cmdCriarTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.create';
    input: { titulo: string; details: { descricao?: string; etiquetas?: string }; prioridade: 'baixa' | 'media' | 'alta'; prazo?: string; listaId: string; responsavelId: string; criadorId: string; tarefaPaiId?: string };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['criarTarefaExigePodeCriar', 'podeCriarTarefasExigido', 'participanteNaoConfiguradoAceitaECria', 'responsavelAceitaTarefas', 'escolhaResponsavelPeloNome', 'tarefaPaiDiferenteDaPropria', 'avisarQuemAgeAgora'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Acrescenta itens marcáveis à checklist de uma tarefa.
   * Entrada: tarefaId: tarefa que recebe os itens; itens: ordem, descrição e marcação inicial de concluído de cada novo item (normalmente falso).
   * Processamento: Recusa se a pessoa da sessão não vê a tarefa (itemChecklistSoQuemVeTarefa) ou se a tarefa está concluída ou cancelada (itemChecklistTarefaNaoEncerrada). Grava os itens todos juntos com a marcação informada; concluidoEm é preenchido pelo sistema quando o item já vem marcado. A situação da tarefa não muda (marcarItemNaoMudaSituacao). progressoChecklist é recalculado, nunca gravado.
   * Saída: A tarefa completa com a checklist atualizada e o novo progresso, e seu histórico.
   */
  'tarefas.minhas_tarefas.cmdAdicionarItensChecklist': {
    kind: 'cmd';
    writes: 'ItemChecklist.create';
    input: { tarefaId: string; itens: ItemChecklistNovo[] };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['itemChecklistSoQuemVeTarefa', 'itemChecklistTarefaNaoEncerrada', 'marcarItemNaoMudaSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Salva os campos ajustados de uma tarefa e, quando muda, troca o responsável, sem mudar a situação.
   * Entrada: id e version da tarefa; titulo, details.descricao, prioridade, prazo, listaId, responsavelId, tarefaPaiId e details.etiquetas com os novos valores.
   * Processamento: Recusa se a pessoa não vê a tarefa (membroVeResponsavelOuCriador) ou se a version mudou. Nunca altera status (edicaoNaoMudaSituacao). Se responsavelId mudou, exige que a pessoa seja quem criou (reatribuirApenasCriadorOuGestor) e que o novo seja participante ativo que aceita tarefas (responsavelAceitaTarefas, escolhaResponsavelPeloNome), e avisa o novo responsável quando ele passa a agir agora (avisarQuemAgeAgora). Recusa tarefa pai igual à própria ou a uma subtarefa (tarefaPaiDiferenteDaPropria).
   * Saída: A tarefa completa nos novos valores, com a mesma situação, e seu histórico incluindo a troca de responsável quando houver.
   */
  'tarefas.minhas_tarefas.cmdSalvarAlteracoes': {
    kind: 'cmd';
    writes: 'Tarefa.update';
    input: { id: string; version: number; titulo: string; details: { descricao?: string; etiquetas?: string }; prioridade: 'baixa' | 'media' | 'alta'; prazo?: string; listaId: string; responsavelId: string; tarefaPaiId?: string };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['edicaoNaoMudaSituacao', 'membroVeResponsavelOuCriador', 'reatribuirApenasCriadorOuGestor', 'responsavelAceitaTarefas', 'escolhaResponsavelPeloNome', 'tarefaPaiDiferenteDaPropria', 'avisarQuemAgeAgora'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Edita, reordena, marca ou desmarca itens da checklist de uma tarefa.
   * Entrada: tarefaId: tarefa dos itens; itens: id, version e os novos valores de ordem, descrição ou concluído de cada item.
   * Processamento: Recusa se a pessoa não vê a tarefa (itemChecklistSoQuemVeTarefa), se a tarefa está concluída ou cancelada (itemChecklistTarefaNaoEncerrada), se algum item não pertence à tarefa ou se a version mudou. Grava os itens; concluidoEm é preenchido pelo sistema ao marcar e limpo ao desmarcar. A situação da tarefa não muda (marcarItemNaoMudaSituacao).
   * Saída: A tarefa completa com a checklist atualizada e o novo progresso, e seu histórico.
   */
  'tarefas.minhas_tarefas.cmdAjustarChecklist': {
    kind: 'cmd';
    writes: 'ItemChecklist.update';
    input: { tarefaId: string; itens: ItemChecklistAjuste[] };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['itemChecklistSoQuemVeTarefa', 'itemChecklistTarefaNaoEncerrada', 'marcarItemNaoMudaSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Inicia a tarefa de que a pessoa é responsável.
   * Entrada: id e version da tarefa.
   * Processamento: Recusa se a pessoa da sessão não é o responsável (apenasResponsavelExecuta), se a tarefa não está em aFazer ou se a version mudou. Passa a emAndamento; o responsável continua sendo quem age agora (quemAgeAgoraPorSituacao).
   * Saída: A tarefa completa em andamento e seu histórico com o início.
   */
  'tarefas.minhas_tarefas.cmdIniciar': {
    kind: 'cmd';
    writes: 'Tarefa.iniciar';
    input: { id: string; version: number };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['apenasResponsavelExecuta', 'quemAgeAgoraPorSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Envia para revisão de quem criou a tarefa em andamento do responsável.
   * Entrada: id e version da tarefa.
   * Processamento: Recusa se a pessoa não é o responsável (apenasResponsavelExecuta), se a tarefa não está emAndamento ou se a version mudou. Passa a emRevisao; quem criou passa a agir agora (quemAgeAgoraPorSituacao) e é avisado (avisarQuemAgeAgora).
   * Saída: A tarefa completa em revisão e seu histórico com o envio.
   */
  'tarefas.minhas_tarefas.cmdEnviarParaRevisao': {
    kind: 'cmd';
    writes: 'Tarefa.enviarParaRevisao';
    input: { id: string; version: number };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['apenasResponsavelExecuta', 'quemAgeAgoraPorSituacao', 'avisarQuemAgeAgora'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Aceita a entrega de uma tarefa em revisão criada pela pessoa.
   * Entrada: id e version da tarefa.
   * Processamento: Recusa se a pessoa não é quem criou (apenasCriadorRevisa), se a tarefa não está emRevisao ou se a version mudou. Passa a concluida e registra concluidaEm; ninguém age agora (quemAgeAgoraPorSituacao).
   * Saída: A tarefa completa concluída e seu histórico com o aceite.
   */
  'tarefas.minhas_tarefas.cmdAceitar': {
    kind: 'cmd';
    writes: 'Tarefa.aceitar';
    input: { id: string; version: number };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['apenasCriadorRevisa', 'quemAgeAgoraPorSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Devolve ao responsável, com motivo, uma tarefa em revisão criada pela pessoa.
   * Entrada: id e version da tarefa; details.motivoDevolucao: o que precisa ser corrigido.
   * Processamento: Recusa se a pessoa não é quem criou (apenasCriadorRevisa), se a tarefa não está emRevisao, se a version mudou ou se o motivo está vazio (devolucaoExigeMotivo). Grava o motivo, registra devolvidaEm e volta a emAndamento; o responsável passa a agir agora (quemAgeAgoraPorSituacao) e é avisado (avisarQuemAgeAgora).
   * Saída: A tarefa completa em andamento com o motivo da devolução e devolvida aguardando retomada, e seu histórico com a devolução.
   */
  'tarefas.minhas_tarefas.cmdDevolver': {
    kind: 'cmd';
    writes: 'Tarefa.devolver';
    input: { id: string; version: number; details: { motivoDevolucao: string } };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['apenasCriadorRevisa', 'devolucaoExigeMotivo', 'quemAgeAgoraPorSituacao', 'avisarQuemAgeAgora'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Retoma a tarefa devolvida para continuar o trabalho.
   * Entrada: id e version da tarefa.
   * Processamento: Recusa se a pessoa não é o responsável (apenasResponsavelExecuta), se a version mudou ou se a tarefa não está emAndamento devolvida e ainda não retomada (retomarSoAposDevolucao). Registra retomadaEm e mantém emAndamento; devolvidaPendente passa a falso por cálculo.
   * Saída: A tarefa completa em andamento já retomada e seu histórico com a retomada.
   */
  'tarefas.minhas_tarefas.cmdRetomar': {
    kind: 'cmd';
    writes: 'Tarefa.retomar';
    input: { id: string; version: number };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['apenasResponsavelExecuta', 'retomarSoAposDevolucao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
  /**
   * Finalidade: Cancela uma tarefa criada pela pessoa.
   * Entrada: id e version da tarefa.
   * Processamento: Recusa se a pessoa não é quem criou nem gestor (cancelarApenasCriadorOuGestor), se a tarefa não está em aFazer, emAndamento ou emRevisao ou se a version mudou. Passa a cancelada e registra canceladaEm; quem estava agindo é avisado (avisarQuemAgeAgora) e ninguém age agora (quemAgeAgoraPorSituacao).
   * Saída: A tarefa completa cancelada e seu histórico com o cancelamento.
   */
  'tarefas.minhas_tarefas.cmdCancelar': {
    kind: 'cmd';
    writes: 'Tarefa.cancelar';
    input: { id: string; version: number };
    output: { tarefa: TarefaCompleta; historico: EventoHistorico[] };
    rules: ['cancelarApenasCriadorOuGestor', 'avisarQuemAgeAgora', 'quemAgeAgoraPorSituacao'];
    access: { actors: ['membroEquipe']; grants: ['membroTarefasProprias', 'membroChecklistPropria', 'membroEscolherResponsavel', 'membroConsultarListas']; scope: 'own' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/painel_tarefas.defs.ts" enhancement="_blank"/>

/** Contagens da situação geral das tarefas da organização: abertas, que vencem hoje, atrasadas e devolvidas aguardando retomada. */
export interface IndicadoresTarefas {
  readonly tarefasAbertas: number;
  readonly vencemHoje: number;
  readonly atrasadas: number;
  readonly devolvidasPendentes: number;
}

/** Tarefa aberta de uma lista, com o título e o progresso da sua checklist. */
export interface ResumoTarefaLista {
  id: string;
  titulo: string;
  listaId: string;
  details: {
    readonly progressoChecklist?: string;
  };
}

/** Lista de tarefas (projeto ou área) com a quantidade de tarefas abertas, os totais de itens de checklist concluídos e existentes nas suas tarefas abertas, e as tarefas abertas que têm checklist. */
export interface ResumoLista {
  id: string;
  nome: string;
  details: {
    readonly quantidadeTarefasAbertas: number;
  };
  readonly itensChecklistConcluidos: number;
  readonly itensChecklistTotal: number;
  tarefas: ResumoTarefaLista[];
}

export interface Painel_tarefasContracts {
  /**
   * Finalidade: Carrega, numa única chamada, o painel do gestor: os quatro indicadores gerais das tarefas da organização e o resumo das tarefas abertas por lista com o progresso das checklists.
   * Entrada: Nenhuma entrada; o gestor é identificado pela sessão.
   * Processamento: Verifica que a pessoa da sessão é gestor pelo acesso da plataforma (gestorPorAcessoPlataforma) e considera todas as tarefas da organização, sem o filtro de membro (membroVeResponsavelOuCriador: o gestor vê todas). Conta no servidor, com tarefaAbertaVencimento: abertas (situação diferente de concluida e cancelada), que vencem hoje (abertas com prazo igual à data de hoje), atrasadas (abertas com prazo anterior a hoje) e devolvidas pendentes (em andamento, devolvidas e ainda não retomadas após a última devolução). Para cada lista, ordenada pelo nome, calcula a quantidade de tarefas abertas, conta os itens de checklist totais e concluídos das tarefas abertas da lista e traz as tarefas abertas que têm checklist com o progresso calculado (itens marcados de total). Todos esses valores são derivados e calculados na consulta, nunca gravados.
   * Saída: indicadores com as quatro contagens já calculadas; listas com cada lista de tarefas, seu nome, quantidade de tarefas abertas, totais de itens de checklist concluídos e existentes e as tarefas abertas com título e progresso da checklist.
   */
  'tarefas.painel_tarefas.carregarPainelTarefas': {
    kind: 'qry';
    input: {};
    output: { indicadores: IndicadoresTarefas; listas: ResumoLista[] };
    rules: ['tarefaAbertaVencimento', 'membroVeResponsavelOuCriador', 'gestorPorAcessoPlataforma'];
    access: { actors: ['gestor']; grants: ['gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/participantes.defs.ts" enhancement="_blank"/>

/** Usuário da organização que participa do módulo de tarefas, com sua situação, papéis, as marcas do gestor e as marcas efetivas de aceitar e criar tarefas. */
export interface ParticipanteModulo {
  id: string;
  version: number;
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
      readonly tags: string;
    };
    tarefas: {
      aceitaTarefas?: boolean;
      podeCriarTarefas?: boolean;
      readonly aceitaTarefasEfetivo: boolean;
      readonly podeCriarTarefasEfetivo: boolean;
    };
  };
}

/** Usuário ativo da organização que ainda não participa do módulo de tarefas, identificado apenas pelo nome lido da plataforma. */
export interface UsuarioOrganizacao {
  id: string;
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
  };
}

export interface ParticipantesContracts {
  /**
   * Finalidade: Lista os participantes do módulo de tarefas da organização, com busca opcional pelo nome.
   * Entrada: busca: trecho do nome do participante (opcional); page e pageSize: página pedida e tamanho da página.
   * Processamento: Localiza pelo papel tarefas.Participante os registros da organização, filtra pelo nome quando há busca e ordena pelo nome. Calcula aceitaTarefasEfetivo e podeCriarTarefasEfetivo pela regra participanteNaoConfiguradoAceitaECria: marca vazia vale sim; os campos efetivos são calculados, nunca gravados. Devolve só identificação e marcas do módulo, sem dado pessoal.
   * Saída: Página { items, page, pageSize, hasMore } de participantes com id, versão, nome, situação, papéis, marcas do gestor (vazias quando não configurado) e marcas efetivas.
   */
  'tarefas.participantes.listarParticipantes': {
    kind: 'qry';
    input: { busca?: string; page: number; pageSize: number };
    output: { participantes: { items: ParticipanteModulo[]; page: number; pageSize: number; hasMore: boolean } };
    rules: ['participanteNaoConfiguradoAceitaECria'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca pelo nome, entre os usuários da organização, quem pode ser incluído como participante.
   * Entrada: busca: trecho do nome do usuário digitado pelo gestor.
   * Processamento: Consulta a lista de usuários da plataforma pelo nome, mantém apenas usuários ativos que ainda não têm o papel tarefas.Participante e limita o resultado aos primeiros encontrados. Pela regra participanteSemCadastroPessoal não lê nem devolve dado pessoal, apenas o nome.
   * Saída: Lista curta de usuários com id, nome e situação.
   */
  'tarefas.participantes.buscarUsuarios': {
    kind: 'qry';
    input: { busca: string };
    output: { usuarios: UsuarioOrganizacao[] };
    rules: ['participanteSemCadastroPessoal'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes']; scope: 'organization' };
  };
  /**
   * Finalidade: Inclui um usuário da organização como participante do módulo de tarefas.
   * Entrada: id: id do usuário escolhido na busca; details.tarefas.aceitaTarefas e details.tarefas.podeCriarTarefas: marcas opcionais do gestor, deixadas vazias quando não informadas.
   * Processamento: Verifica pelo acesso da plataforma que quem chama é gestor (gestorPorAcessoPlataforma). Marca o papel tarefas.Participante no registro do usuário e grava só o espaço do módulo, sem cadastrar pessoa nem pedir dado pessoal (participanteSemCadastroPessoal). Marcas não informadas ficam vazias e valem sim (participanteNaoConfiguradoAceitaECria); marcas já existentes do gestor não são sobrescritas automaticamente (escolhaGestorNuncaSobrescrita). Os campos efetivos são calculados na leitura.
   * Saída: O participante incluído, no novo estado, com versão, marcas do gestor e marcas efetivas.
   */
  'tarefas.participantes.incluirParticipante': {
    kind: 'cmd';
    writes: 'Participante.create';
    input: { id: string; details: { tarefas: { aceitaTarefas?: boolean; podeCriarTarefas?: boolean } } };
    output: { participante: ParticipanteModulo };
    rules: ['participanteSemCadastroPessoal', 'participanteNaoConfiguradoAceitaECria', 'escolhaGestorNuncaSobrescrita', 'gestorPorAcessoPlataforma'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes']; scope: 'organization' };
  };
  /**
   * Finalidade: Grava as marcas de aceitar tarefas e de poder criar tarefas de um participante.
   * Entrada: id e version: participante escolhido e versão lida, para concorrência otimista; details.tarefas.aceitaTarefas e details.tarefas.podeCriarTarefas: marcas escolhidas pelo gestor.
   * Processamento: Verifica pelo acesso da plataforma que quem chama é gestor (gestorPorAcessoPlataforma) e recusa se a versão mudou. Grava as duas marcas só no espaço do módulo; por escolhaGestorNuncaSobrescrita, só o gestor altera essas marcas e nenhum processo automático as substitui. Os campos efetivos são recalculados (participanteNaoConfiguradoAceitaECria), nunca gravados. A mudança fica registrada na auditoria da plataforma.
   * Saída: O participante no novo estado, com a nova versão, as marcas do gestor e as marcas efetivas.
   */
  'tarefas.participantes.salvarMarcas': {
    kind: 'cmd';
    writes: 'Participante.update';
    input: { id: string; version: number; details: { tarefas: { aceitaTarefas: boolean; podeCriarTarefas: boolean } } };
    output: { participante: ParticipanteModulo };
    rules: ['escolhaGestorNuncaSobrescrita', 'participanteNaoConfiguradoAceitaECria', 'gestorPorAcessoPlataforma'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes']; scope: 'organization' };
  };
}

/// <mls fileReference="_102047_/l2/tarefas/web/contracts/tarefas_equipe.defs.ts" enhancement="_blank"/>

/** Tarefa da organização em forma resumida, com a lista, o responsável, quem age agora e as marcas de vencimento já calculadas. */
export interface TarefaResumo {
  id: string;
  version: number;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'baixa' | 'media' | 'alta';
  prazo?: string;
  listaId: string;
  listaTarefas: {
    nome: string;
  };
  responsavelId: string;
  participante: {
    details: {
      identification: {
        name: string;
      };
    };
  };
  readonly criadaEm: string;
  details: {
    readonly quemAgeAgora?: string;
    readonly venceHoje: boolean;
    readonly atrasada: boolean;
    readonly progressoChecklist: string;
  };
  readonly quemAgeAgoraNome?: string;
}

/** Quantidade de tarefas em uma situação, dentro dos filtros aplicados. */
export interface ContagemSituacao {
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  readonly quantidade: number;
}

/** Lista de tarefas identificada pelo nome. */
export interface ListaOpcao {
  id: string;
  nome: string;
}

/** Participante do módulo identificado pelo nome, com a situação na plataforma e se aceita tarefas. */
export interface ParticipanteOpcao {
  id: string;
  details: {
    identification: {
      name: string;
      readonly status: 'Active' | 'Inactive' | 'Merged' | 'Blocked';
    };
    tarefas: {
      readonly aceitaTarefasEfetivo: boolean;
    };
  };
}

/** Item da checklist de uma tarefa, na sua ordem, com a marca de concluído. */
export interface ItemChecklistLinha {
  id: string;
  ordem: number;
  details: {
    descricao: string;
    concluido: boolean;
    readonly concluidoEm?: string;
  };
}

/** Evento do ciclo de uma tarefa (criação, início, envio para revisão, devolução, retomada, conclusão, troca de responsável ou cancelamento) com o momento em que ocorreu. */
export interface EventoTarefa {
  readonly tipo: string;
  readonly momento: string;
  details: {
    motivoDevolucao?: string;
  };
  readonly responsavelNome?: string;
}

/** Tarefa completa com lista, responsável, quem criou, quem age agora, subtarefas, checklist em ordem e o histórico de eventos. */
export interface TarefaDetalhe {
  id: string;
  version: number;
  titulo: string;
  status: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada';
  prioridade: 'baixa' | 'media' | 'alta';
  prazo?: string;
  listaId: string;
  listaTarefas: {
    nome: string;
  };
  responsavelId: string;
  participante: {
    details: {
      identification: {
        name: string;
      };
    };
  };
  criadorId: string;
  readonly criadorNome: string;
  details: {
    readonly quemAgeAgora?: string;
    descricao?: string;
    readonly aberta: boolean;
    readonly quantidadeSubtarefas: number;
    readonly progressoChecklist: string;
  };
  readonly quemAgeAgoraNome?: string;
  readonly criadaEm: string;
  checklist: ItemChecklistLinha[];
  historico: EventoTarefa[];
}

export interface Tarefas_equipeContracts {
  /**
   * Finalidade: Carrega as opções dos filtros de lista e de responsável da visão de tarefas da equipe.
   * Entrada: Nenhuma entrada; o gestor é identificado pela sessão.
   * Processamento: Lê as listas de tarefas ordenadas pelo nome e os participantes do módulo pelo papel tarefas.Participante, ordenados pelo nome. aceitaTarefasEfetivo é calculado (participanteNaoConfiguradoAceitaECria: sem configuração vale sim), nunca gravado.
   * Saída: As listas de tarefas (id e nome) e os participantes (id, nome, situação na plataforma e se aceita tarefas).
   */
  'tarefas.tarefas_equipe.carregarFiltrosEquipe': {
    kind: 'qry';
    input: {};
    output: { listas: ListaOpcao[]; participantes: ParticipanteOpcao[] };
    rules: ['participanteNaoConfiguradoAceitaECria'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
  /**
   * Finalidade: Lista todas as tarefas da organização com os filtros do gestor, servindo tanto a visão em lista quanto o quadro por situação.
   * Entrada: listaId, responsavelId, prioridade e status: filtros opcionais por igualdade; prazoDe e prazoAte: intervalo opcional de prazo; page e pageSize: página pedida.
   * Processamento: Executa ao abrir a página (sem filtros) e a cada mudança de filtro ou página. O gestor, definido pelo acesso da plataforma (gestorPorAcessoPlataforma), vê todas as tarefas (membroVeResponsavelOuCriador). Ordena por criadaEm decrescente. Junta o nome da lista e os nomes do responsável e de quem age agora. Calcula quemAgeAgora pela situação (quemAgeAgoraPorSituacao), venceHoje e atrasada (tarefaAbertaVencimento) e progressoChecklist contando itens marcados sobre o total; nada disso é gravado. Conta as tarefas por situação sob os mesmos filtros, sem paginação.
   * Saída: A página de tarefas resumidas { items, page, pageSize, hasMore } e a quantidade de tarefas em cada situação para os mesmos filtros.
   */
  'tarefas.tarefas_equipe.listarTarefasEquipe': {
    kind: 'qry';
    input: { listaId?: string; responsavelId?: string; prioridade?: 'baixa' | 'media' | 'alta'; status?: 'aFazer' | 'emAndamento' | 'emRevisao' | 'concluida' | 'cancelada'; prazoDe?: string; prazoAte?: string; page: number; pageSize: number };
    output: { tarefas: { items: TarefaResumo[]; page: number; pageSize: number; hasMore: boolean }; contagemPorSituacao: ContagemSituacao[] };
    rules: ['membroVeResponsavelOuCriador', 'gestorPorAcessoPlataforma', 'quemAgeAgoraPorSituacao', 'tarefaAbertaVencimento'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
  /**
   * Finalidade: Abre uma tarefa da organização com tudo que o gestor confere antes de agir: responsável, prazo, checklist, subtarefas e histórico.
   * Entrada: tarefaId: id da tarefa escolhida na lista ou no quadro.
   * Processamento: Lê a tarefa pelo id, junta o nome da lista e os nomes do responsável, de quem criou e de quem age agora. Lista os itens da checklist pela tarefa em ordem. Calcula quemAgeAgora (quemAgeAgoraPorSituacao), aberta (tarefaAbertaVencimento), quantidadeSubtarefas contando as tarefas que apontam esta como pai e progressoChecklist; nada disso é gravado. Monta o histórico em ordem de tempo a partir de criadaEm, devolvidaEm com motivo, retomadaEm, concluidaEm, canceladaEm e dos eventos de mudança de situação e reatribuição da ocorrência do processo de tarefa da plataforma. Comentários e anexos não vêm daqui (moduloNaoGuardaComentarios).
   * Saída: A tarefa no estado atual, com sua checklist ordenada e o histórico de eventos em ordem de tempo.
   */
  'tarefas.tarefas_equipe.obterTarefaEquipe': {
    kind: 'qry';
    input: { tarefaId: string };
    output: { tarefa: TarefaDetalhe };
    rules: ['quemAgeAgoraPorSituacao', 'tarefaAbertaVencimento', 'moduloNaoGuardaComentarios'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
  /**
   * Finalidade: Busca pelo nome os participantes que podem ser escolhidos como novo responsável.
   * Entrada: nome: trecho do nome digitado; vazio traz os primeiros por ordem alfabética.
   * Processamento: Filtra participantes ativos que aceitam tarefas (responsavelAceitaTarefas), com aceitaTarefasEfetivo calculado como sim quando o gestor não configurou (participanteNaoConfiguradoAceitaECria). A busca é só pelo nome, nunca pelo e-mail (escolhaResponsavelPeloNome). Limita a uma quantidade curta de resultados ordenados pelo nome.
   * Saída: Os participantes elegíveis encontrados, com id, nome, situação e se aceita tarefas.
   */
  'tarefas.tarefas_equipe.buscarResponsaveisDisponiveis': {
    kind: 'qry';
    input: { nome?: string };
    output: { participantes: ParticipanteOpcao[] };
    rules: ['responsavelAceitaTarefas', 'escolhaResponsavelPeloNome', 'participanteNaoConfiguradoAceitaECria'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
  /**
   * Finalidade: Troca o responsável de uma tarefa pelo participante escolhido pelo gestor.
   * Entrada: id: tarefa a reatribuir; version: versão lida, para concorrência otimista; responsavelId: novo responsável escolhido pelo nome.
   * Processamento: Recusa quem não é o criador nem gestor pelo acesso da plataforma (reatribuirApenasCriadorOuGestor, gestorPorAcessoPlataforma). Recusa responsável inativo ou que não aceita tarefas (responsavelAceitaTarefas). Recusa versão divergente. Grava só o responsável, sem mudar a situação (edicaoNaoMudaSituacao). Quando a tarefa está a fazer ou em andamento, o novo responsável passa a ser quem age agora (quemAgeAgoraPorSituacao, calculado, não gravado) e a ocorrência do processo da plataforma troca e avisa essa pessoa (avisarQuemAgeAgora).
   * Saída: A tarefa no novo estado, com o novo responsável, quem age agora recalculado, checklist e histórico incluindo a troca.
   */
  'tarefas.tarefas_equipe.trocarResponsavelTarefa': {
    kind: 'cmd';
    writes: 'Tarefa.update';
    input: { id: string; version: number; responsavelId: string };
    output: { tarefa: TarefaDetalhe };
    rules: ['reatribuirApenasCriadorOuGestor', 'gestorPorAcessoPlataforma', 'responsavelAceitaTarefas', 'edicaoNaoMudaSituacao', 'quemAgeAgoraPorSituacao', 'avisarQuemAgeAgora'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
  /**
   * Finalidade: Cancela uma tarefa ainda aberta a pedido do gestor.
   * Entrada: id: tarefa a cancelar; version: versão lida, para concorrência otimista.
   * Processamento: Recusa quem não é o criador nem gestor pelo acesso da plataforma e recusa tarefa que não está a fazer, em andamento ou em revisão (cancelarApenasCriadorOuGestor, gestorPorAcessoPlataforma). Recusa versão divergente. Aplica a transição cancelar, levando a situação a cancelada e registrando canceladaEm. Antes de trocar, identifica quem estava agindo e o processo da plataforma o avisa (avisarQuemAgeAgora); depois quem age agora passa a ser ninguém (quemAgeAgoraPorSituacao, calculado).
   * Saída: A tarefa cancelada, não mais aberta, sem quem age agora, com checklist e histórico incluindo o cancelamento.
   */
  'tarefas.tarefas_equipe.cancelarTarefaEquipe': {
    kind: 'cmd';
    writes: 'Tarefa.cancelar';
    input: { id: string; version: number };
    output: { tarefa: TarefaDetalhe };
    rules: ['cancelarApenasCriadorOuGestor', 'gestorPorAcessoPlataforma', 'avisarQuemAgeAgora', 'quemAgeAgoraPorSituacao'];
    access: { actors: ['gestor']; grants: ['gestorParticipantes', 'gestorListas', 'gestorTodasTarefas']; scope: 'organization' };
  };
}
